// The site's service worker (tools/build_site.py writes it to site/sw.js, with UNITS and AUDIO filled in above).
// github.io is slow in China, and the iPad may be offline: once a unit (week, poem, episode) has been opened, all its
// pages and recordings are kept on the iPad, so it plays again without the network.
//   audio      cache-first: AUDIO knows each file's content hash, so a re-recorded file is a new entry, never stale
//   the rest   network-first (pages, css, js, voice.js): a new version reaches the iPad at once; the cache is only
//              used when the network fails
// iPad Safari asks for <audio> in byte ranges (and playTake seeks with currentTime): a range request answered with
// the whole file (200) does not play, so a cached file is answered with the 206 piece asked for.

const CACHE = 'huiben-1';   // bump when the way things are kept changes: activate then drops the old cache
const ROOT = new URL('./', self.location).href;
const audioKey = (path) => `${ROOT}${path}?v=${AUDIO[path]}`;   // the hash in the key: a new recording, a new entry

self.addEventListener('install', () => self.skipWaiting());   // an update takes over at once, no waiting for tabs to close
self.addEventListener('activate', (e) => e.waitUntil((async () => {
  for (const name of await caches.keys()) if (name !== CACHE) await caches.delete(name);
  // recordings this build no longer has (or has re-recorded) go
  const c = await caches.open(CACHE), keep = new Set(Object.keys(AUDIO).map(audioKey));
  for (const req of await c.keys()) if (/\.(m4a|mp3|wav)\?v=/.test(req.url) && !keep.has(req.url)) await c.delete(req);
  await self.clients.claim();
})()));

// a page asks to keep itself, its css / js and its whole unit (sent on load by the script in every page's head)
self.addEventListener('message', (e) => {
  const urls = ((e.data && e.data.keep) || []).filter((u) => u.startsWith(ROOT));   // only this site's own files
  if (!urls.length) return;
  const unit = new URL('./', urls[0]).href.slice(ROOT.length);   // 'w01/', 'shici/p01/', '' for the home page
  e.waitUntil(Promise.all([
    ...[...new Set([...urls, ...(UNITS[unit] || []).map((p) => ROOT + p)])].map((u) => keepPage(u)),   // the page is in both
    keepAll(Object.keys(AUDIO).filter((p) => unit && p.startsWith(unit))),
  ]));
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || !req.url.startsWith(ROOT)) return;
  const path = decodeURIComponent(new URL(req.url).pathname.slice(new URL(ROOT).pathname.length));
  if (path in AUDIO) e.respondWith(audio(req, path));
  else e.respondWith(networkFirst(req));
});

// ---------- pages, css, js: the network first ----------
// a ?v= address changes with its content, so the browser's own cache may answer it; anything else is checked with the server
const fresh = (url) => (new URL(url).searchParams.has('v') ? 'default' : 'no-cache');
async function put(c, url, res) {
  if (res.status !== 200 || res.redirected) return;   // a redirected answer cannot be given back for a page later
  // an older ?v= of the same file is not needed any more
  for (const old of await c.keys(url, { ignoreSearch: true })) if (old.url !== url) await c.delete(old);
  await c.put(url, res);
}
async function networkFirst(req) {
  const c = await caches.open(CACHE);
  try {
    const res = await fetch(req, { cache: fresh(req.url) });
    if (res.ok) await put(c, req.url, res.clone());
    return res;
  } catch (err) {   // offline: what was kept, else the same file at another ?v=, else w01/ ↔ w01/index.html
    const alt = req.url.endsWith('/') ? req.url + 'index.html' : req.url.replace(/index\.html$/, '');
    return (await c.match(req.url)) || (await c.match(req.url, { ignoreSearch: true })) || (await c.match(alt)) || Response.error();
  }
}
async function keepPage(url) {
  try {
    const c = await caches.open(CACHE), res = await fetch(url, { cache: fresh(url) });
    if (res.ok) await put(c, url, res);
  } catch (err) { /* offline: kept next time */ }
}

// ---------- audio: the cache first ----------
// A unit's recordings are kept one at a time, in the order its pages play them, and only while the page is not
// fetching one itself: all at once, a first visit on a slow line had page 1's recording wait behind 40–100 others
// (the browser opens 6 connections to a server) and page 1 stayed silent. A recording the page asks for stops the one
// being kept (it is fetched again later), unless the page is waiting for that one.
const QUIET = 1500;   // ms after the page's last recording came in (or was dropped) before keeping goes on
const queue = [];
let pageFetching = 0, quietSince = 0, keeping = null, keepingAll = null;
function keepAll(paths) {
  for (const p of paths) if (!queue.includes(p)) queue.push(p);
  return keepingAll = keepingAll || (async () => {
    while (queue.length) {
      while (pageFetching || Date.now() - quietSince < QUIET) await new Promise((r) => setTimeout(r, 250));
      const path = queue[0], stop = new AbortController();
      keeping = { path, stop, wanted: false };
      try { await keepAudio(path, stop.signal); queue.shift(); } catch (err) { if (!stop.signal.aborted) queue.shift(); }   // offline: next time
      keeping = null;
    }
  })().finally(() => { keepingAll = null; });
}
// the page fetches a recording: nothing kept meanwhile, until the page has its last byte or drops it (turned the page:
// the download stops too)
async function forPage(path, get) {
  pageFetching++;
  if (keeping && !keeping.wanted && keeping.path !== path) keeping.stop.abort();
  let over = false;
  const done = () => { if (!over) { over = true; pageFetching--; quietSince = Date.now(); } };
  setTimeout(done, 30000);   // an answer nobody reads nor drops does not hold the keeping up for good
  try {
    const res = await get();
    if (!res.body) { done(); return res; }
    const reader = res.body.getReader();
    return new Response(new ReadableStream({
      async pull(out) {
        try {
          const { value, done: end } = await reader.read();
          if (end) { out.close(); done(); } else out.enqueue(value);
        } catch (err) { out.error(err); done(); }
      },
      cancel(why) { done(); return reader.cancel(why); },
    }), { status: res.status, statusText: res.statusText, headers: res.headers });
  } catch (err) { done(); throw err; }
}

const loading = {};   // a file being fetched, so a page asking for it while it is kept does not fetch it twice
function keepAudio(path, signal) {
  const key = audioKey(path);
  return loading[key] = loading[key] || (async () => {
    const c = await caches.open(CACHE);
    let res = await c.match(key);
    if (!res) {
      // no-cache: the browser's copy may still be the recording before this build's
      const got = await fetch(ROOT + path, { cache: 'no-cache', signal });
      if (got.status !== 200) throw new Error(`${path}: ${got.status}`);
      await c.put(key, got.clone());
      res = got;
    }
    return res;
  })().finally(() => delete loading[key]);
}
async function audio(req, path) {
  const range = req.headers.get('range');
  const hit = await (await caches.open(CACHE)).match(audioKey(path));
  if (hit) return range ? piece(hit, range) : hit;
  // being kept right now: that copy; else the server answers the range (the file is kept later, in its turn)
  if (range && keeping && keeping.path === path) {
    keeping.wanted = true;
    try { return piece((await (loading[audioKey(path)] || keepAudio(path))).clone(), range); } catch (err) { /* stopped: the server */ }
  }
  if (range) return forPage(path, () => fetch(req));
  try { return (await forPage(path, () => keepAudio(path))).clone(); } catch (err) { return fetch(req); }
}
// the bytes asked for in "bytes=start-end" (or "bytes=-n": the last n), as a 206
async function piece(res, range) {
  const blob = await res.blob(), size = blob.size, m = /^bytes=(\d*)-(\d*)/.exec(range.trim());
  let start = m && m[1] ? +m[1] : NaN, end = m && m[2] ? +m[2] : size - 1;
  if (m && !m[1] && m[2]) { start = Math.max(0, size - +m[2]); end = size - 1; }
  end = Math.min(end, size - 1);
  if (!(start >= 0) || start >= size || end < start) {
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  }
  return new Response(blob.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': res.headers.get('Content-Type') || blob.type || 'audio/mp4',
      'Content-Range': `bytes ${start}-${end}/${size}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}
